// Compare reported gust ceilings at one fixed mean wind, using the panel's
// nominal tuning and both layers together. Optional raw frames aid look review.
#include "wled_stub.hpp"
#include <cassert>
#include <fstream>
#include <string>
#include "../leaves_effect.hpp"
#include "../wind_effect.hpp"

// AI: below section was generated by an AI
struct ChaosMetrics {
  unsigned lifts = 0, landings = 0, samples = 0, lifted = 0, above = 0;
  double vertical = 0, neighbours = 0, crowdedFrames = 0;
  unsigned longestCrowd = 0;
};

static ChaosMetrics run(float gust, bool left, const char *framePrefix) {
  strip.now = 1000;
  resetPanelAir();
  leafExchange = {};
  Segment litter(32, 12), air(32, 16);
  litter.startY = 4; litter.custom3 = 6; litter.intensity = 245;
  air.check2 = true; air.intensity = 1; air.custom2 = 152;
  const uint32_t palette[] = {0xa9ac11, 0xf29831, 0xab773c};
  for (unsigned i = 0; i < 3; i++) litter.colors[i] = air.colors[i] = palette[i];
  WindInputs wind{};
  wind.meanMps = 5.1f; wind.gustMps = gust;
  wind.airMean = 86; wind.airGust = uint8_t(min(255.0f, 70 + (gust - 4) * 185 / 13));
  wind.activity = uint8_t(255 * sqrtf(min(1.0f, (gust - 1) / 14) * min(1.0f, (gust - 5.1f) / 7)));
  wind.turbulence = 150; wind.blowLeft = left;
  ChaosMetrics result;
  std::ofstream frames;
  if (framePrefix && !left) frames.open(std::string(framePrefix) + "-" + std::to_string(int(gust * 10)) + ".rgb", std::ios::binary);
  unsigned crowdRun[LEAVES_CAPACITY] = {};
  for (unsigned frame = 0; frame < 3600; frame++) {
    strip.now += 33;
    currentSegment = &litter;
    renderLeavesToSegment(litter, wind);
    currentSegment = &air;
    renderWindToSegment(air, wind, 6); // actual 0.6 particles/s at 5.1 mean
    const auto &ground = *reinterpret_cast<LeavesState *>(litter.data);
    unsigned neighbours = 0, crowded = 0;
    for (unsigned i = 0; i < LEAVES_CAPACITY; i++) {
      const auto &leaf = ground.particles[i];
      if (!leaf.active) { crowdRun[i] = 0; continue; }
      assert(std::isfinite(leaf.x) && std::isfinite(leaf.y));
      result.samples++;
      result.lifted += leaf.height > 0.3f;
      result.above += leaf.y < 5.5f;
      unsigned local = 0;
      for (unsigned j = 0; j < LEAVES_CAPACITY; j++) {
        const auto &other = ground.particles[j];
        if (!other.active || i == j) continue;
        if (fabsf(leaf.x - other.x) < 1.5f && fabsf(leaf.y - other.y) < 1.5f) local++;
      }
      neighbours += local;
      crowded += local >= 5;
      crowdRun[i] = local >= 5 ? crowdRun[i] + 1 : 0;
      result.longestCrowd = max(result.longestCrowd, crowdRun[i]);
    }
    result.neighbours += neighbours / 2.0;
    result.crowdedFrames += crowded > 0;
    const auto &runtime = *reinterpret_cast<WindState *>(air.data);
    for (unsigned i = 0; i < runtime.particleCount; i++) {
      const auto &leaf = getWindParticles(const_cast<WindState *>(&runtime))[i];
      if (leaf.state) {
        assert(std::isfinite(leaf.motionX) && std::isfinite(leaf.motionY));
        result.vertical += fabsf(leaf.motionY) / 3600;
      }
    }
    if (frames.is_open() && frame % 3 == 0) {
      for (int y = 0; y < 16; y++) for (int x = 0; x < 32; x++) {
        uint32_t color = y >= 10 ? 0x39341f : 0x596770;
        if (y >= 4) { const uint32_t leaf = litter.pixel(x, y - 4); color = color_blend(color, leaf, W(leaf)); }
        const uint32_t leaf = air.pixel(x, y); color = color_blend(color, leaf, W(leaf));
        const char rgb[] = {char(R(color)), char(G(color)), char(B(color))};
        frames.write(rgb, sizeof(rgb));
      }
    }
    assert(litter.outOfBoundsWrites == 0 && air.outOfBoundsWrites == 0);
  }
  result.lifts = leafExchange.liftsTaken; result.landings = leafExchange.landingsTaken;
  result.neighbours /= 3600; result.crowdedFrames /= 3600;
  printf("gust %.1f%s: lifts %u, landings %u, lifted %.2f%%, above %.2f%%, air vertical %.2f, close pairs %.2f, crowded %.2f%%, longest crowd %.2fs\n",
    gust, left ? " left" : "", result.lifts, result.landings, 100.0 * result.lifted / result.samples,
    100.0 * result.above / result.samples, result.vertical, result.neighbours, result.crowdedFrames * 100, result.longestCrowd * 0.033);
  return result;
}

int main(int argc, char **argv) {
  const char *prefix = argc > 1 ? argv[1] : nullptr;
  for (bool left : {false, true}) {
    const auto today = run(11.5f, left, prefix);
    const auto strong = run(15, left, prefix);
    const auto storm = run(20, left, prefix);
    if (argc > 2) continue; // measurement of previous firmware for comparison
    assert(storm.lifts >= 12 && storm.lifts > today.lifts * 3);
    assert(storm.vertical > today.vertical * 2);
    assert(strong.lifted / double(strong.samples) > today.lifted / double(today.samples) * 2);
    assert(storm.lifted / double(storm.samples) > strong.lifted / double(strong.samples) * 1.5);
    for (const auto &m : {today, strong, storm}) {
      assert(m.neighbours > 1 && m.neighbours < 20);
      assert(m.longestCrowd * 0.033 < 3.0); // encounters disperse instead of forming persistent piles
    }
  }
}
// AI: end
